import { defineConfig } from 'vite';

export default defineConfig({
  server: {
    host: '127.0.0.1',
    port: 5173,
  },
});

import js from '@eslint/js';
import tseslint from 'typescript-eslint';

export default tseslint.config(
  {
    ignores: ['dist/**', 'coverage/**', 'node_modules/**'],
  },
  js.configs.recommended,
  ...tseslint.configs.strict,
  {
    files: ['**/*.ts'],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      '@typescript-eslint/no-non-null-assertion': 'off',
      '@typescript-eslint/no-floating-promises': 'off',
      '@typescript-eslint/no-extraneous-class': 'off'
    },
  },
);

export class SeededRandom {
  private state: number;

  public constructor(seed: number) {
    this.state = seed >>> 0;
  }

  public next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let value = this.state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  }

  public int(maxExclusive: number): number {
    if (maxExclusive <= 0) {
      throw new Error(`maxExclusive must be positive, got ${maxExclusive}`);
    }
    return Math.floor(this.next() * maxExclusive);
  }

  public range(minInclusive: number, maxExclusive: number): number {
    if (maxExclusive <= minInclusive) {
      throw new Error(`invalid range ${minInclusive}..${maxExclusive}`);
    }
    return minInclusive + this.int(maxExclusive - minInclusive);
  }

  public chance(probability: number): boolean {
    if (probability < 0 || probability > 1) {
      throw new Error(`probability must be between 0 and 1, got ${probability}`);
    }
    return this.next() < probability;
  }

  public pick<T>(values: readonly T[]): T {
    if (values.length === 0) {
      throw new Error('cannot pick from an empty list');
    }
    return values[this.int(values.length)]!;
  }

  public weighted<T>(entries: readonly { value: T; weight: number }[]): T {
    const total = entries.reduce((sum, entry) => sum + entry.weight, 0);
    if (total <= 0) {
      throw new Error('weighted choice requires a positive total weight');
    }
    let roll = this.next() * total;
    for (const entry of entries) {
      roll -= entry.weight;
      if (roll <= 0) {
        return entry.value;
      }
    }
    return entries[entries.length - 1]!.value;
  }

  public fork(salt: number): SeededRandom {
    return new SeededRandom(mixSeed(this.state, salt));
  }

  public currentState(): number {
    return this.state >>> 0;
  }
}

export function mixSeed(seed: number, salt: number): number {
  let value = (seed ^ Math.imul(salt >>> 0, 0x9e3779b9)) >>> 0;
  value ^= value >>> 16;
  value = Math.imul(value, 0x7feb352d) >>> 0;
  value ^= value >>> 15;
  value = Math.imul(value, 0x846ca68b) >>> 0;
  value ^= value >>> 16;
  return value >>> 0;
}

export function seedFromQuery(search: string): number {
  const params = new URLSearchParams(search);
  const raw = params.get('seed');
  if (raw === null || raw.trim() === '') {
    return 13371337;
  }
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isFinite(parsed)) {
    return 13371337;
  }
  return parsed >>> 0;
}

export const TILE_SIZE = 32;

export type TileType = 'grass' | 'dirt' | 'forest' | 'water' | 'rock' | 'gold';
export type ResourceKind = 'gold' | 'wood';
export type FactionId = 'humans' | 'orcs';
export type SideId = 0 | 1;
export type UnitType = 'worker' | 'melee' | 'ranged' | 'heavy';
export type BuildingType = 'townHall' | 'farm' | 'barracks' | 'lumberMill' | 'guardTower';
export type EntityKind = 'unit' | 'building';
export type GameStatus = 'menu' | 'playing' | 'victory' | 'defeat';
export type FogState = 0 | 1 | 2;

export interface Point {
  x: number;
  y: number;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface StartLocation extends Point {
  label: 'player' | 'ai';
}

export interface LevelDefinition {
  level: number;
  name: string;
  width: number;
  height: number;
  difficulty: number;
  waterWeight: number;
  rockWeight: number;
  forestWeight: number;
  description: string;
}

export interface GameMap {
  width: number;
  height: number;
  tiles: TileType[];
  gold: Int32Array;
  wood: Int32Array;
  starts: [StartLocation, StartLocation];
}

export interface UnitStats {
  type: UnitType;
  humanName: string;
  orcName: string;
  hp: number;
  armor: number;
  damage: number;
  range: number;
  cooldown: number;
  speed: number;
  sight: number;
  goldCost: number;
  woodCost: number;
  supplyCost: number;
  trainingTime: number;
  projectile: boolean;
}

export interface BuildingStats {
  type: BuildingType;
  humanName: string;
  orcName: string;
  hp: number;
  armor: number;
  goldCost: number;
  woodCost: number;
  buildTime: number;
  footprint: { width: number; height: number };
  sight: number;
  supplyProvided: number;
  trains: readonly UnitType[];
  attackDamage: number;
  attackRange: number;
  attackCooldown: number;
}

export interface Resources {
  gold: number;
  wood: number;
}

export interface SupplyState {
  used: number;
  cap: number;
}

export type UnitOrder =
  | { kind: 'idle' }
  | { kind: 'move'; target: Point; attackMove: boolean }
  | { kind: 'attack'; targetId: number; attackMove: boolean }
  | { kind: 'harvest'; resource: ResourceKind; target: Point; returnAfterDropoff: boolean }
  | { kind: 'returnResources'; resource: ResourceKind; harvestTarget: Point }
  | { kind: 'build'; buildingId: number }
  | { kind: 'repair'; targetId: number };

export interface TrainingQueueItem {
  unitType: UnitType;
  remaining: number;
  total: number;
}

export interface Entity {
  id: number;
  owner: SideId;
  kind: EntityKind;
  type: UnitType | BuildingType;
  faction: FactionId;
  x: number;
  y: number;
  radius: number;
  hp: number;
  maxHp: number;
  armor: number;
  sight: number;
  completed: boolean;
  buildProgress: number;
  buildTime: number;
  attackDamage: number;
  attackRange: number;
  attackCooldown: number;
  cooldownRemaining: number;
  projectileAttack: boolean;
  unit?: {
    speed: number;
    supplyCost: number;
    carried: { kind: ResourceKind; amount: number } | null;
    order: UnitOrder;
    path: Point[];
    pathIndex: number;
    stuckTime: number;
    formationOffset: Point;
  };
  building?: {
    footprint: { width: number; height: number };
    supplyProvided: number;
    trainQueue: TrainingQueueItem[];
  };
}

export interface Projectile {
  id: number;
  owner: SideId;
  source: Point;
  x: number;
  y: number;
  targetId: number;
  damage: number;
  speed: number;
  color: string;
}

export interface Corpse {
  x: number;
  y: number;
  radius: number;
  color: string;
  remaining: number;
  total: number;
}

export interface PlayerState {
  side: SideId;
  faction: FactionId;
  resources: Resources;
  aiHarvestBonus: number;
}

export interface SelectionSummary {
  entities: Entity[];
  primary: Entity | null;
}

