import { describe, expect, it } from 'vitest';
import { generateLevelMap, mapHash, tileCanNeighbor, validateAdjacency } from '../src/wfc';

function countTile(map: ReturnType<typeof generateLevelMap>, tile: string): number {
  return map.tiles.filter((candidate) => candidate === tile).length;
}

describe('WFC map generation', () => {
  it('BA: produces deterministic maps for a fixed campaign seed and level', () => {
    const first = generateLevelMap(424242, 2);
    const second = generateLevelMap(424242, 2);

    expect(mapHash(first)).toBe(mapHash(second));
    expect(first.tiles).toEqual(second.tiles);
    expect(first.starts).toEqual(second.starts);
  });

  it('BA: propagates adjacency constraints across the collapsed map', () => {
    const map = generateLevelMap(99117, 3);

    expect(validateAdjacency(map.tiles, map.width, map.height)).toBe(true);
    expect(tileCanNeighbor('water', 'grass')).toBe(false);
    expect(tileCanNeighbor('gold', 'forest')).toBe(false);
    expect(tileCanNeighbor('water', 'dirt')).toBe(true);
  });

  it('BG: repairs generated terrain into two fair playable starts with resources', () => {
    const map = generateLevelMap(20260610, 1);
    const [player, ai] = map.starts;

    expect(map.starts).toHaveLength(2);
    expect(player.label).toBe('player');
    expect(ai.label).toBe('ai');
    expect(Math.abs(player.x - ai.x)).toBeGreaterThan(14);
    expect(countTile(map, 'gold')).toBeGreaterThanOrEqual(2);
    expect(countTile(map, 'forest')).toBeGreaterThan(20);
  });
});

import { describe, expect, it } from 'vitest';
import { findPath, pathDistance, type Grid } from '../src/pathfinding';

function grid(width: number, height: number, blocked: readonly string[]): Grid {
  const blockedSet = new Set(blocked);
  return {
    width,
    height,
    isPassable(x: number, y: number): boolean {
      return x >= 0 && y >= 0 && x < width && y < height && !blockedSet.has(`${x},${y}`);
    },
  };
}

describe('A* pathfinding', () => {
  it('BA: finds an octile-shortest route on open terrain', () => {
    const path = findPath(grid(6, 6, []), { x: 0, y: 0 }, { x: 3, y: 4 });

    expect(path[0]).toEqual({ x: 0, y: 0 });
    expect(path[path.length - 1]).toEqual({ x: 3, y: 4 });
    expect(pathDistance(path)).toBeCloseTo(3 * Math.SQRT2 + 1, 6);
    expect(path.length).toBe(5);
  });

  it('BA: refuses diagonal movement through blocked corners', () => {
    const path = findPath(grid(3, 3, ['1,0', '0,1']), { x: 0, y: 0 }, { x: 2, y: 2 });

    expect(path).toEqual([]);
  });

  it('BA: returns an empty path when the goal cannot be reached', () => {
    const path = findPath(grid(5, 5, ['0,2', '1,2', '2,2', '3,2', '4,2']), { x: 0, y: 0 }, { x: 4, y: 4 });

    expect(path).toHaveLength(0);
  });
});

import { describe, expect, it } from 'vitest';
import { UNIT_STATS } from '../src/data';
import { calculateSupply, canReserveSupply, computeDamage } from '../src/mechanics';
import { GameSimulation } from '../src/simulation';

describe('combat and supply mechanics', () => {
  it('BA: applies armor reduction with a minimum damage floor', () => {
    expect(computeDamage(9, 2)).toBe(7);
    expect(computeDamage(3, 99)).toBe(1);
    expect(computeDamage(16, 0)).toBe(16);
  });

  it('BG: counts living units, completed supply buildings, and queued training', () => {
    const sim = new GameSimulation({ campaignSeed: 101, level: 1, playerFaction: 'humans' });
    const supplyBefore = sim.getSupply(0);
    const townHall = sim.buildingsForSide(0).find((entity) => entity.type === 'townHall');
    if (townHall === undefined) {
      throw new Error('test setup expected a starting town hall');
    }

    expect(supplyBefore.used).toBe(5);
    expect(supplyBefore.cap).toBe(10);
    expect(sim.queueTraining(townHall.id, 'worker').ok).toBe(true);
    expect(sim.getSupply(0).used).toBe(6);
    expect(calculateSupply(sim.players[0], sim.entities.values())).toEqual(sim.getSupply(0));
  });

  it('BG: blocks training when reserved supply reaches the cap', () => {
    const sim = new GameSimulation({ campaignSeed: 202, level: 1, playerFaction: 'orcs' });
    const townHall = sim.buildingsForSide(0).find((entity) => entity.type === 'townHall');
    if (townHall === undefined) {
      throw new Error('test setup expected a starting hall');
    }
    sim.players[0].resources.gold = 10_000;
    sim.players[0].resources.wood = 10_000;

    for (let i = 0; i < 5; i += 1) {
      expect(sim.queueTraining(townHall.id, 'worker').ok).toBe(true);
    }
    expect(sim.getSupply(0)).toEqual({ used: 10, cap: 10 });
    expect(canReserveSupply(sim.players[0], sim.entities.values(), 'worker')).toBe(false);
    expect(sim.queueTraining(townHall.id, 'worker')).toEqual({ ok: false, reason: 'Supply cap reached. Build more Farms.' });
    expect(UNIT_STATS.worker.supplyCost).toBe(1);
  });
});

