export function validateAdjacency(tiles: readonly TileType[], width: number, height: number): boolean {
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const tile = tiles[indexOf(x, y, width)]!;
      const right = x + 1 < width ? tiles[indexOf(x + 1, y, width)] : undefined;
      const down = y + 1 < height ? tiles[indexOf(x, y + 1, width)] : undefined;
      if (right !== undefined && !tileCanNeighbor(tile, right)) {
        return false;
      }
      if (down !== undefined && !tileCanNeighbor(tile, down)) {
        return false;
      }
    }
  }
  return true;
}

function collapseWfc(width: number, height: number, weights: CollapseWeights, rng: SeededRandom): TileType[] | null {
  const domains = new Int32Array(width * height);
  domains.fill(ALL_MASK);

  while (true) {
    const cell = selectMinimumEntropyCell(domains, width, height, weights, rng);
    if (cell === -1) {
      return masksToTiles(domains);
    }
    const tile = chooseTileFromMask(domains[cell]!, weights, rng);
    domains[cell] = bitFor(tile);
    if (!propagate(domains, width, height, [cell])) {
      return null;
    }
  }
}

function selectMinimumEntropyCell(
  domains: Int32Array,
  width: number,
  height: number,
  weights: CollapseWeights,
  rng: SeededRandom,
): number {
  let bestCell = -1;
  let bestEntropy = Number.POSITIVE_INFINITY;
  for (let i = 0; i < width * height; i += 1) {
    const mask = domains[i]!;
    const count = countBits(mask);
    if (count <= 1) {
      continue;
    }
    const entropy = entropyForMask(mask, weights) + rng.next() * 0.000001;
    if (entropy < bestEntropy) {
      bestEntropy = entropy;
      bestCell = i;
    }
  }
  return bestCell;
}

function propagate(domains: Int32Array, width: number, height: number, queue: number[]): boolean {
  while (queue.length > 0) {
    const cell = queue.shift();
    if (cell === undefined) {
      throw new Error('queue reported an element but returned undefined');
    }
    const x = cell % width;
    const y = Math.floor(cell / width);
    const allowedAround = allowedNeighborMask(domains[cell]!);
    const neighbors = [
      x > 0 ? cell - 1 : -1,
      x + 1 < width ? cell + 1 : -1,
      y > 0 ? cell - width : -1,
      y + 1 < height ? cell + width : -1,
    ];
    for (const neighbor of neighbors) {
      if (neighbor < 0) {
        continue;
      }
      const oldMask = domains[neighbor]!;
      const newMask = oldMask & allowedAround;
      if (newMask === 0) {
        return false;
      }
      if (newMask !== oldMask) {
        domains[neighbor] = newMask;
        queue.push(neighbor);
      }
    }
  }
  return true;
}

